package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.relatorio.*; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RelatorioSacramentoApplicationService { private final RelatorioSacramentoRepository repo; private final SegurancaOrganizacaoService seguranca; public RelatorioSacramentoApplicationService(RelatorioSacramentoRepository r,SegurancaOrganizacaoService s){repo=r;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioSacramentoRegistroItem> registros(RelatorioSacramentoFiltro f){validar(f);var pg=repo.registros(f.organizacaoUuid(),tipo(f),f.dataInicio(),f.dataFim(),nome(f),PageRequest.of(pagina(f),tamanho(f)));var itens=pg.getContent().stream().map(x->new RelatorioSacramentoRegistroItem(x.getUuid(),x.getTipo(),x.getDataCelebracao(),x.getPessoaPrincipal(),x.getLocal(),x.getStatus(),x.getLivro(),x.getFolha(),x.getTermo(),x.getNumeroRegistro())).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),pg.getTotalElements(),pg.getTotalPages(),"dataCelebracao","desc");}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioSacramentoPessoaItem> pessoas(RelatorioSacramentoFiltro f){validar(f);var pg=repo.pessoas(f.organizacaoUuid(),tipo(f),f.dataInicio(),f.dataFim(),nome(f),PageRequest.of(pagina(f),tamanho(f)));var itens=pg.getContent().stream().map(x->new RelatorioSacramentoPessoaItem(x.getPessoaUuid(),x.getPessoa(),x.getTipo(),x.getDataCelebracao(),x.getSacramentoUuid(),x.getStatus())).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),pg.getTotalElements(),pg.getTotalPages(),"pessoa","asc");}
 private void validar(RelatorioSacramentoFiltro f){if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória");if(f.dataInicio()!=null&&f.dataFim()!=null&&f.dataFim().isBefore(f.dataInicio()))throw new IllegalArgumentException("Data final não pode ser anterior à data inicial");seguranca.validarAcesso(f.organizacaoUuid());} private String tipo(RelatorioSacramentoFiltro f){return f.tipo()==null?null:f.tipo().name();} private String nome(RelatorioSacramentoFiltro f){return f.pessoa()==null||f.pessoa().isBlank()?null:f.pessoa().trim();} private int pagina(RelatorioSacramentoFiltro f){return Math.max(0,f.pagina());} private int tamanho(RelatorioSacramentoFiltro f){return Math.max(10,Math.min(100,f.tamanho()));}
}
